SELECT  FROM (
  SELECT r.*, ROW_NUMBER() OVER (PARTITION BY verify_case_id ORDER BY start_time DESC, verify_run_id DESC) rn
  FROM t_channel_verify_run r WHERE verify_case_id IN
  #{id}
) latest WHERE rn=1

SELECT  FROM (
  SELECT r.*, ROW_NUMBER() OVER (PARTITION BY verify_case_id ORDER BY start_time DESC, verify_run_id DESC) rn
  FROM t_channel_verify_run r WHERE run_status <> 'RUNNING' AND verify_case_id IN
  #{id}
) latest WHERE rn=1

